  mykhailo2: { n: 'Mihail Vsevolodovitš Tšernihivistä', p: 'Tšernihiv', d: 'Kiovan viimeinen suvereeni suuriruhtinas (1238–39, 1241–43): jätti kaupungin ennen Batun rynnäkköä, kieltäytyi ordan epäjumalallisista riiteistä ja kuoli marttyyrinä 1246 — kirkko laskee hänet pyhiinsä.' },
