  baibuza: { n: 'Tyhin Baibuza', p: 'Zaporižžjan Sitš', d: 'Zaporižžjan kasakoiden hetmani, jonka 1597 retket ulottuivat Tonavan linnoituksiin — sukulinjan hämärimmistä nimistä, säilynyt kansanlaulussa.' },
  izapovich: { n: 'Hryhorii Izapovytš', p: 'Zaporižžjan Sitš', d: 'Rekisteröityjen hetmani suuressa retkikymmenluvussa: hänen vuonnaan tšaikat paloivat jälleen Krimin ja Osmanien rannikoilla.' },
  borodavka: { n: 'Jakiv Borodavka-Neroda', p: 'Zaporižžjan Sitš', d: 'Rekisteröimättömän armeijan hetmani Rzeszówin sopimuksen 1619 halki; syösty vallasta ja tapettu Hotynin leirissä 1621, kun Sahaidatšnyi otti nuijan sotaan.' },
  doroshenko_m: { n: 'Myhailo Doroshenko', p: 'Tšerkasy, Ukraina', d: 'Hetmani, joka palautti kasakoiden maineen Tetšoran jälkeen — arvostettu sekä tsaarin että kuninkaan taholta — ja johti kuuluisan Krimin sotaretken 1628 kaatuen Perekopin lähellä.' },
  chorny: { n: 'Hrytsko Tšornyi', p: 'Zaporižžjan Sitš', d: 'Kahdesti rekisteröityjen hetmani: toimeenpani Kurukiven ehdot, ja sitšin kapinalliset vastasivat hänelle hirttotuomiolla (1630).' },
  tryasylo: { n: 'Taras Fedorovytš (Trjasylo)', p: 'Zaporižžjan Sitš', d: 'Košatamani ja ”alamaan hetmani”, joka johti vuoden 1630 kansannousua: Perejaslavin voitto pakotti kruunun kaksinkertaistamaan rekisterin — hyökkäyksen yötä muistetaan Taraksen yönä.' },
