  vyhovsky: { n: 'Ivan Vyhovskyi', p: 'Hadjatš, Ukraina', d: 'Hetmani 1657–59: hänen Hadjatšin liittonsa palautti Ukrainan liittotasavallaan Rusin ruhtinaskuntana, ja Konotop tuhosi moskovalaisen armeijan — mutta Kiovan everstit eivät antaneet hänelle anteeksi oligarkin olemusta; kasakkakilpailijoiden murhaama (1664).' },
  teterya: { n: 'Pavlo Teterja', p: 'Korsun, Ukraina', d: 'Oikean rannan hetmani puolalaisella radalla (1663–66): pakeni Moldovaan kun omat everstit kapinoivat, ja kuoli siellä.' },
  briukhovetsky: { n: 'Ivan Brjuhovetskyi', p: 'Hadjatš, Ukraina', d: 'Moskovalainen nukkehallitsija vasemman rannan hetmanina (1663–68): hän suuteli ristiä tsaarille — ja kapinoi sitten kuvernöörien ja verojen alla; joukko, joka nousi hänen kanssaan, repi hänet kappaleiksi.' },
  doroshenko_p: { n: 'Petro Doroshenko', p: 'Tšyhyryn, Ukraina', d: 'Ruinon paras valtiomies: hetmani oikeasta rannasta ja sitten molemmista rannoista pelasi Varsovalla, Moskvalla ja Istanbulilla itsenäisen kasakkaruhtinaskunnan puolesta, piti Tšyhyrynin kaikilta — ja päätti arvokkaassa maanpaossa Moskovan liepeillä.' },
