  khanenko: { n: 'Myhailo Hanenko', p: 'Uman, Ukraina', d: 'Oikean rannan pro-puolalaisen puolueen hetmani (1669–74): taisteli puolalaisin armeijin Doroshenkoa vastaan — ja hävisi sekä tälle että ordalle.' },
  samus: { n: 'Samiilo Samus', p: 'Korsun, Ukraina', d: 'Herätetyn oikean rannan armeijan hetmani (1693–1704): piti palautetut rykmentit taistelussa ordan kanssa kunnes antoi nuijan Mazepalle.' },
