  skoropadsky_i: { n: 'Ivan Skoropadskyi', p: 'Hluhiv, Ukraina', d: 'Hetmani, valittu Mazepan loikkauksen jälkeen (1708–22): uskollinen Pietari I:lle ja siitä huolimatta vallasta riistetty — keisarillinen kollegio hallitsi hänen rinnallaan hetmanaatin tyhjentyessä.' },
  polubotok: { n: 'Pavlo Polubotok', p: 'Hluhiv, Ukraina', d: 'Vs. hetmani (1722–24): armeijan rikkain mies jätti adressin kasakoiden oikeuksista ja kuoli Pietarin linnoituksessa — alku legendalle hänen kultaisesta testamentistaan Lontoon pankissa.' },
  apostol: { n: 'Danylo Apostol', p: 'Hluhiv, Ukraina', d: 'Hetmani (1727–34), viimeinen valittu: voitti viran takaisin kollegiovuosien jälkeen — ja kun hän kuoli, keisarikunta pysäytti hetmanaatin jälleen.' },
  rozumovsky: { n: 'Kyrylo Rozumovskyi', p: 'Baturyn, Ukraina', d: 'Viimeinen hetmani (1750–64): keisarinnan suosikin veli, joka elvytti hetmanaatin tuomioistuimet ja suunnitteli Baturynille yliopistoa — ja antoi nuijan, kun Katariina II lakkautti viran.' },
  orlyk: { n: 'Pylyp Orlyk — hetmani maanpaossa', p: 'Bender (maanpaossa)', d: 'Valittu Benderissä Poltavan jälkeen ja vuoden 1710 ”Paktin ja perustuslain” laatija; kokosi tataari-ruotsalaisia armeijoita Ukrainan paluun puolesta ja kuoli Iașissa — nuija eli valtiota pidempään.' },
  zalizniak: { n: 'Maksym Zaliznjak', p: 'Uman, Ukraina', d: 'Sitšikasakko, joka julistettiin hetmaniksi vuoden 1768 Kolijivštšynassa: kansannousu valtasi Umanin ja ravisteli liittotasavaltaa, kunnes venäläiset sotaväki lopetti sen; hänen kohtalonsa karkotuksen jälkeen on kansantarina.' },
