  eng_alfred: { n: 'Alfred Suuri', p: 'Winchester, Englanti', d: 'Wessexin kuningas, joka poltti pullat ja löi Suuren pakana-armeijan — ainoa englantilainen kuningas ”Suuri”, ensimmäinen joka kutsui itseään anglosaksien kuninkaaksi.' },
  eng_edward_elder: { n: 'Edvard Vanhempi', p: 'Winchester, Englanti', d: 'Valtasi eteläisen Danelawin kaupunki kerrallaan ja kutsui itseään, isänsä mallin mukaan, anglosaksien kuninkaaksi.' },
