  eng_edmund_i: { n: 'Edmund I', p: 'Winchester, Englanti', d: 'Palautti luostariliikkeen ja murhatun edeltäjänsä kultin — tapettu pidotissa karkotetun lainsuojattoman toimesta (946).' },
